shaders.source:
struct Uniforms {
  mvp : mat4x4<f32>,
  normalMatrix : mat3x3<f32>,
  deepJade : vec3<f32>,
  paleJade : vec3<f32>,
  rimTint : vec3<f32>,
};
@group(0) @binding(0) var<uniform> u : Uniforms;

struct VertexInput {
  @location(0) position : vec3<f32>,
  @location(1) normal : vec3<f32>,
  @location(2) uv : vec2<f32>,
};

struct VertexOutput {
  @builtin(position) position : vec4<f32>,
  @location(0) vNormal : vec3<f32>,
  @location(1) vUv : vec2<f32>,
};

@vertex
fn vertexMain(in : VertexInput) -> VertexOutput {
  var out : VertexOutput;
  out.vNormal = in.normal;
  out.vUv = in.uv;
  out.position = (u.mvp * vec4<f32>(in.position, 1.0));
  return out;
}

@fragment
fn fragmentMain(in : VertexOutput) -> @location(0) vec4<f32> {
  let n = normalize(in.vNormal);
  let thickness = clamp((1.0 - abs(n.y)), 0.0, 1.0);
  let internal = (sin(((in.vUv.x + in.vUv.y) * 18.0)) * 0.035);
  let body = mix(u.deepJade.rgb, u.paleJade.rgb, ((thickness * 0.62) + internal));
  let rim = (pow((1.0 - abs(n.z)), 3.0) * 0.22);
  return vec4<f32>(mix(body, u.rimTint.rgb, rim), 0.94);
}

shaders.vertex:
#version 300 es
in vec3 position;
in vec3 normal;
in vec2 uv;
uniform mat4 mvp;
uniform mat3 normalMatrix;
uniform vec3 deepJade;
uniform vec3 paleJade;
uniform vec3 rimTint;
out vec3 vNormal;
out vec2 vUv;

void main() {
  vNormal = normal;
  vUv = uv;
  gl_Position = (mvp * vec4(position, 1.0));
}

shaders.fragment:
#version 300 es
precision highp float;
uniform mat4 mvp;
uniform mat3 normalMatrix;
uniform vec3 deepJade;
uniform vec3 paleJade;
uniform vec3 rimTint;
in vec3 vNormal;
in vec2 vUv;
out vec4 fragColor;

void main() {
  vec3 n = normalize(vNormal);
  float thickness = clamp((1.0 - abs(n.y)), 0.0, 1.0);
  float internal = (sin(((vUv.x + vUv.y) * 18.0)) * 0.035);
  vec3 body = mix(deepJade.rgb, paleJade.rgb, ((thickness * 0.62) + internal));
  float rim = (pow((1.0 - abs(n.z)), 3.0) * 0.22);
  fragColor = vec4(mix(body, rimTint.rgb, rim), 0.94);
}
